var wordsEnglish=['I','lost','part','of','my','self','when','Im','speaking','English','Hi','How are you','Good',"Thanks",'cool',
									'ok','ok cool','awesome','yeah','I know','alright','you too','have a good one','can I','yes please','i guess',
									'sure','no problem','appreciate it','thank you','hello','S-I-H-A-N','do you mean','nice to meet you','haha'];
var wordsChinese=['在','说','英','语','的','时','候','，','我','丧','失','了','一','部','分','自','我'];
var words1=[];
var words2=[];  

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(100); 

	for(let i=0;i<wordsChinese.length;i++){
		let word = new Word(wordsChinese[i],width/2-wordsChinese.length/2*20+i*20,height/2,255,true);
		words1.push(word);
	}

		for(let i=0;i<wordsEnglish.length;i++){
		var word = new Word(wordsEnglish[i],random(0,width),random(0,height),0);
		words2.push(word);
	}

	// for(let w of wordsEnglish){
	// 	text(w,random(0,width),random(0,height));
	// }
}

function draw() {
	background(233,233,233);

	for(let w of words1){
		w.move();
		w.show();
	}

	for(let w of words2){
		//w.move()
		w.fade();
		w.show();
	}

	if(frameCount%60==0&&words2.length<2000){
		for(let i=0;i<wordsEnglish.length;i++){
			var word = new Word(wordsEnglish[i],random(0,width),random(0,height),0);
			words2.push(word);	
			//words2[i]=word;
		}
	}


}

class Word{
	constructor(char,x,y,alpha,haveStroke=false){

		this.fadeSpeed=random(1,3);
		this.x=x;
		this.y=y;
		this.char=char;
		this.fadingIn=true;
		this.alpha=alpha;
		this.haveStroke=haveStroke;

	}
	move(){
		this.x+=random(-1,1);
		this.y+=random(-1,1);
	}
	show(){
		if(this.haveStroke){
			 stroke(244, 244, 0, this.alpha); 
			 strokeWeight(2); 
		}else{
			noStroke();
		}
		fill(0,0,0, this.alpha);
		text(this.char,this.x,this.y);
	}
	fade(){
		if (this.fadingIn) {
    this.alpha += this.fadeSpeed; 
    if (this.alpha >= 255) { 
      this.alpha = 255;
      this.fadingIn = false; 
    }
  } else {
    this.alpha -= this.fadeSpeed; 
    if (this.alpha <= 0) { 
      this.alpha = 0;
      this.fadingIn = true; 
    }
  }
	}
}
